def count_adjacent_frame(grid, r, c, frame_val):
    """Count adjacent frame neighbors (up to 2 in a line from the cell)"""
    count = 0

    # Up direction
    up_cnt = 0
    for dr in range(1, 10):  # check up to 9 cells
        nr = r - dr
        if nr >= 0:
            if grid[nr][c] == frame_val:
                up_cnt += 1
            else:
                break
        else:
            break
    count += min(up_cnt, 2)

    # Down direction
    down_cnt = 0
    for dr in range(1, 10):
        nr = r + dr
        if nr < len(grid):
            if grid[nr][c] == frame_val:
                down_cnt += 1
            else:
                break
        else:
            break
    count += min(down_cnt, 2)

    # Left direction
    left_cnt = 0
    for dc in range(1, 10):
        nc = c - dc
        if nc >= 0:
            if grid[r][nc] == frame_val:
                left_cnt += 1
            else:
                break
        else:
            break
    count += min(left_cnt, 2)

    # Right direction
    right_cnt = 0
    for dc in range(1, 10):
        nc = c + dc
        if nc < len(grid[0]):
            if grid[r][nc] == frame_val:
                right_cnt += 1
            else:
                break
        else:
            break
    count += min(right_cnt, 2)

    return count

